def countSubarraysK(nums: list[int], k: int) -> int:
    max_val = max(nums)
    ans = left = count = 0
    for right, x in enumerate(nums):
        if x == max_val: count += 1
        while count >= k:
            if nums[left] == max_val: count -= 1
            left += 1
        ans += left
    return ans

